BEGIN;
SET LOCAL lock_timeout = '5s';

CREATE TABLE IF NOT EXISTS "InternalAuditPlan" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "auditNumber" bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  title varchar(180) NOT NULL CHECK (length(trim(title)) >= 5),
  process varchar(160) NOT NULL,
  scope text NOT NULL CHECK (length(trim(scope)) >= 5),
  criteria text NOT NULL CHECK (length(trim(criteria)) >= 3),
  "leadAuditor" varchar(200) NOT NULL,
  auditee varchar(200) NOT NULL,
  "plannedDate" date NOT NULL,
  status varchar(24) NOT NULL DEFAULT 'PLANNED'
    CHECK (status IN ('PLANNED','IN_PROGRESS','CLOSURE_REVIEW','CLOSED','CANCELLED')),
  "createdBy" uuid NOT NULL REFERENCES "HRUser"(id),
  "updatedBy" uuid NOT NULL REFERENCES "HRUser"(id),
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  "closedAt" timestamptz
);
CREATE INDEX IF NOT EXISTS "InternalAuditPlan_status_date_idx"
  ON "InternalAuditPlan"(status,"plannedDate");
CREATE INDEX IF NOT EXISTS "InternalAuditPlan_created_idx"
  ON "InternalAuditPlan"("createdAt" DESC);

CREATE TABLE IF NOT EXISTS "InternalAuditChecklistItem" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "auditId" uuid NOT NULL REFERENCES "InternalAuditPlan"(id) ON DELETE CASCADE,
  reference varchar(100) NOT NULL DEFAULT '',
  question text NOT NULL CHECK (length(trim(question)) >= 5),
  "sortOrder" integer NOT NULL DEFAULT 0,
  response varchar(24) NOT NULL DEFAULT 'PENDING'
    CHECK (response IN ('PENDING','CONFORMING','NONCONFORMING','NOT_APPLICABLE')),
  evidence text NOT NULL DEFAULT '',
  "completedBy" uuid REFERENCES "HRUser"(id),
  "completedAt" timestamptz,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  UNIQUE ("auditId","sortOrder")
);
CREATE INDEX IF NOT EXISTS "InternalAuditChecklistItem_audit_idx"
  ON "InternalAuditChecklistItem"("auditId","sortOrder");

CREATE TABLE IF NOT EXISTS "InternalAuditFinding" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "findingNumber" bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "auditId" uuid NOT NULL REFERENCES "InternalAuditPlan"(id) ON DELETE CASCADE,
  "checklistItemId" uuid REFERENCES "InternalAuditChecklistItem"(id) ON DELETE SET NULL,
  severity varchar(16) NOT NULL CHECK (severity IN ('OBSERVATION','MINOR','MAJOR','CRITICAL')),
  title varchar(180) NOT NULL CHECK (length(trim(title)) >= 5),
  description text NOT NULL CHECK (length(trim(description)) >= 10),
  "actionPlan" text NOT NULL DEFAULT '',
  "actionOwner" varchar(200) NOT NULL DEFAULT '',
  "actionDueDate" date,
  "actionStatus" varchar(20) NOT NULL DEFAULT 'OPEN'
    CHECK ("actionStatus" IN ('OPEN','IN_PROGRESS','COMPLETE')),
  "actionNote" text NOT NULL DEFAULT '',
  "capaRequired" boolean NOT NULL DEFAULT false,
  "capaId" uuid REFERENCES "CAPA"(id) ON DELETE RESTRICT,
  "closureEvidence" text NOT NULL DEFAULT '',
  status varchar(16) NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED')),
  "createdBy" uuid NOT NULL REFERENCES "HRUser"(id),
  "updatedBy" uuid NOT NULL REFERENCES "HRUser"(id),
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  "closedAt" timestamptz
);
CREATE INDEX IF NOT EXISTS "InternalAuditFinding_audit_status_idx"
  ON "InternalAuditFinding"("auditId",status);
CREATE INDEX IF NOT EXISTS "InternalAuditFinding_capa_idx"
  ON "InternalAuditFinding"("capaId") WHERE "capaId" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "InternalAuditEvent" (
  id bigserial PRIMARY KEY,
  "auditId" uuid NOT NULL REFERENCES "InternalAuditPlan"(id) ON DELETE CASCADE,
  "actorId" uuid NOT NULL REFERENCES "HRUser"(id),
  action varchar(32) NOT NULL,
  detail jsonb NOT NULL DEFAULT '{}'::jsonb,
  "createdAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "InternalAuditEvent_audit_time_idx"
  ON "InternalAuditEvent"("auditId","createdAt" DESC,id DESC);
CREATE INDEX IF NOT EXISTS "InternalAuditEvent_created_idx"
  ON "InternalAuditEvent"("createdAt" DESC);

CREATE OR REPLACE FUNCTION aa_internal_audit_event_immutable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Internal audit event history is immutable';
END $$;
DROP TRIGGER IF EXISTS aa_internal_audit_event_immutable_trigger ON "InternalAuditEvent";
CREATE TRIGGER aa_internal_audit_event_immutable_trigger
  BEFORE UPDATE OR DELETE ON "InternalAuditEvent"
  FOR EACH ROW EXECUTE FUNCTION aa_internal_audit_event_immutable();

COMMIT;
